# 使用你的代码替换 ___ 

class BinarySearchTreeNode:
    def __init__(self, data):
        # 定义节点的数据以及左右子节点
        self.data = data
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self, root=None):
        # 初始化一个根节点
        self.root = root

    def insert(self, value, current_node=None):
        # 插入值，如果当前节点为空，则在正确的位置创建新的节点
        if current_node is None:
            if self.root is None:
                self.root = BinarySearchTreeNode(value)
                return
            else:
                current_node = self.root

        if value < current_node.data:
            if current_node.left is None:
                current_node.left = BinarySearchTreeNode(value)
            else:
                self.insert(value, current_node.left)
        elif value > current_node.data:
            if current_node.right is None:
                current_node.right = BinarySearchTreeNode(value)
            else:
                self.insert(value, current_node.right)

    def search(self, value, current_node=None):
        # 搜寻值，如果当前节点为空或值等于当前节点的数据，则返回节点
        if current_node is None:
            current_node = self.root

        if current_node is None:
            return None

        if value == current_node.data:
            return current_node
        elif value < current_node.data:
            return self.search(value, current_node.left) if current_node.left else None
        else:
            return self.search(value, current_node.right) if current_node.right else None

    def delete(self, root, key):
        # 删除指定值的节点
        if not root:
            return root

        if key < root.data:
            root.left = self.delete(root.left, key)
        elif key > root.data:
            root.right = self.delete(root.right, key)
        else:
            if not root.left:
                temp = root.right
                root = None
                return temp
            elif not root.right:
                temp = root.left
                root = None
                return temp

            # 获取右子树的最小值节点
            temp = root.right
            while temp.left:
                temp = temp.left
            root.data = temp.data
            root.right = self.delete(root.right, temp.data)

        return root

    def inorder_traversal(self, node, visited_nodes=None):
        # 使用中序遍历来遍历树
        if visited_nodes is None:
            visited_nodes = []

        if node:
            self.inorder_traversal(node.left, visited_nodes)
            visited_nodes.append(node.data)
            self.inorder_traversal(node.right, visited_nodes)

        return visited_nodes

bst = BinarySearchTree()

values_to_insert = [8,6,10,5,7,9,11]

# 将值插入到二叉搜索树
for value in values_to_insert:
    bst.insert(value)

# 打印中序遍历的结果
print(bst.inorder_traversal(bst.root))

values_to_delete = [10,5]
# 从二叉搜索树中删除值
for value in values_to_delete:
    bst.root = bst.delete(bst.root, value)

# 打印删除后的中序遍历结果
print(bst.inorder_traversal(bst.root))
